   const joined=await rpc('join_link',{token});
   if(!sameOwner(scope))return;
   if(pendingToken===token){pendingToken=null;try{sessionStorage.removeItem('ders-class-invite');}catch{}const u=new URL(location.href);u.searchParams.delete('class_invite');history.replaceState(history.state,'',u);}
   if(current(scope)){message=joined.status==='active'?'Bu sınıfın zaten üyesisin.':'Katılım isteğiniz öğretmene gönderildi.';if(joined.status==='active')selectClass(joined.class_id);}
