   if(a==='send'){const data=detail.section==='members'||!detail.view_version?detail:await read('detail',{class_id:selected,view_version:2,section:'members',period,week_start:week,...periodDates});if(!current(scope))return;await window.DersTeacher.openClassProgram({id:selected,name:detail.class.name,members:data.members.filter(m=>m.connected)});return;}
   if(a==='copy-link'){try{await navigator.clipboard.writeText(joinUrl(detail.link));board.toast('Sınıf davet bağlantısı kopyalandı.');}catch{if(!current(scope))return;modal('Davet Bağlantısı','<p class="class-link">'+esc(joinUrl(detail.link))+'</p>');}return;}
   const actions={'link':['rotate_link',{}],'disable-link':['disable_link',{}],'accept-request':['respond_requests',{ids:[id],status:'accepted'}],'reject-request':['respond_requests',{ids:[id],status:'rejected'}],'cancel-request':['cancel_request',{id}],'pin-program':['pin_program',{id,pinned:b.dataset.pinned==='true'}],'cancel-program':['cancel_program',{id}],'cancel-shared':['cancel_shared',{id}],'delete-announcement':['delete_announcement',{id}],'archive':['archive_class',{}],'leave':['leave',{}],'remove':['remove_member',{student_id:id}]};
   const op=actions[a];if(!op)return;if(['cancel-program','cancel-shared','delete-announcement','archive','leave','remove','link','disable-link'].includes(a)&&!confirm({archive:'Sınıf arşivlensin mi? Geçmiş korunur; yeni etkinlikler durur.',leave:'Sınıftan ayrılasın mı? Kişisel kayıtların ve öğretmen bağlantın korunur.',remove:'Öğrenci sınıftan çıkarılsın mı? Kişisel verileri silinmez.',link:'Yeni bağlantı oluşturulsun mu? Önceki bağlantı geçersizleşir.'}[a]||'Bu işlem uygulansın mı?'))return;
   busy=operation;b.disabled=true;await rpc(op[0],{class_id:cid,request_id:uuid(),...op[1]});if(a==='leave'&&current(scope))selectClass(null);await refresh({fresh:true});if(sameOwner(scope)){window.DersTeacher.refresh();window.DersStudy.refresh();board.toast('Sınıf işlemi tamamlandı.');}
